#!/usr/bin/env python3
# SPDX-License-Identifier: MIT
"""Write test cards and a blank hardware results sheet from the patch manifest."""
import csv, html, json, shutil
from pathlib import Path
ROOT = Path(__file__).resolve().parent
APP = ROOT.parent
OUT = APP / 'build/hardware-tests'
GROUPS = {1: 'RNBO fundamentals', 2: 'Gen synthesis and feedback', 3: 'Gen buffers and delays', 4: 'Effects and signal processing', 5: 'Polyphony and integration'}

def num(x):
    return f'{x:g}' if isinstance(x, (float, int)) else str(x)

def main():
    cases = json.loads((ROOT / 'manifest.json').read_text())['patches']
    results = []
    for c in cases:
        f = OUT / c['id']
        r = json.loads((f / 'result.json').read_text())
        assert r['build'] == 'pass' and r['audition'] == 'pass', r
        if c['id'] in ['t03_lists', 't04_constants']:
            r['measurements'] = json.loads((f / 'audition.log').read_text())
            (f / 'result.json').write_text(json.dumps(r, indent=2) + '\n')
        import hashlib
        assert r['source_sha256'] == hashlib.sha256((ROOT / c['source']).read_bytes()).hexdigest()
        results.append(r)
        (ROOT / 'max').mkdir(exist_ok=True)
        shutil.copy2(f / (c['id'] + '.maxpat'), ROOT / 'max' / (c['id'] + '.maxpat'))
    report = dict(host_builds='15/15 pass', auditions='15/15 pass', slot_groups='5/5 simulator pass', history_ab=json.loads((OUT / 'history-ab.json').read_text()), hardware_test=False, native_build=False, patches=results)
    (ROOT / 'HOST-RESULTS.json').write_text(json.dumps(report, indent=2) + '\n')
    rows = ['# FM1 RNBO playable hardware test collection', '', 'Fifteen standalone patches, arranged into **five groups of three**. Load one group into the FM1’s three patch slots at a time. These groups are a test schedule; the instrument still has only three slots and runs one patch at a time.', '', "**Current status (30 October 2026):** the archived RNBO 1.4.4 host report records all 15 exports, portability audits, host builds and auditions passing, with all five groups passing the player simulator checks. Native build output supplied by the maintainer confirms Groups 4 and 5 pass after adding the integer `abs()` runtime helper needed by T11. Groups 1–4 and T15 have positive user-reported FM1 playback results; T13 has no separate hardware confirmation in the recorded walkthrough. T14 plays, with a quiet-echo observation explained by its `1 - Feedback` input gain. The proposed echo gain revision was deferred and is not included. T08 Mix remains subtle and its hardware audibility is unconfirmed. See `HARDWARE-RESULTS.csv` for per-patch observations; unreported checklist items, CPU readings and package hashes remain blank. These records distinguish archived host evidence from user-reported device results; they do not claim a fresh complete compiler or hardware run.", '', '## Start here', '', '1. Open a file from `max/` in Max to inspect or play it. Audio starts off. The wrapper connects MIDI input and stereo output. Native Max GUI/audio audition has not been performed by this test run.', '2. Use the matching `.rnbopat` in `patches/` as the reproducible RNBO source. Export edited source from inside the RNBO editor; saving only the outer Max wrapper will not update that source.', '3. Start hardware qualification with **Group 1**. Run `../Build-Test-Group-1.command` from normal macOS Terminal with Docker Desktop running. It builds the player and three native modules, reruns auditions and collects verified upload files in a new `build/hardware-tests/group-1-ready-*` folder. Follow its `START-HERE.md` for installation and slot uploads. It does not install or upload automatically.', '4. Use **PRESETS** to switch patches and **FX** to switch between K1–K4 and K5–K8. Every patch has eight controls, with Level on K1, Attack on K7 and Release on K8.', '5. Record actual device observations in `HARDWARE-RESULTS.csv`. Its hardware fields intentionally start blank. Host execution speed and simulator CPU displays are not FM1 CPU measurements.', '', '## Groups', '', '| Group | Slot 1 | Slot 2 | Slot 3 |', '| --- | --- | --- | --- |']
    for bank in range(1, 6):
        group = [c for c in cases if c['bank'] == bank]
        rows.append('| ' + str(bank) + ' — ' + GROUPS[bank] + ' | ' + ' | '.join((c['id'] + ' — ' + c['title'] for c in group)) + ' |')
    rows += ['', '## Build and audition commands', '', "For any group N = 1–5, run `Build-Test-Group-N.command`, then `Upload-Test-Group-N.command` from the rnbo-loader folder. Replace N with the group number. The build reruns export, audits, native compilation and host auditions and collects reviewed packages. The upload validates all three source hashes, module settings and native reviews before replacing slots 1–3. Use `Upload-Test-Group-N.command --check` for validation without transfer. An already installed compatible three-slot visual player needs no reinstall for a patch-only group change. Install a rebuilt player separately when applying player/UI changes. The equivalent preparation command from the repository root is `python3 fm1-base/rnbo-loader/hardware-tests/prepare.py --bank N` after sourcing `setup/env.sh`. Preparation rebuilds the player and does not install or upload.", '', 'From the repository root:', '', '```sh', 'source setup/env.sh', '# Source/config/Max and archived-evidence checks (no RNBO required):', 'python3 fm1-base/rnbo-loader/hardware-tests/check_sources.py', '# Host builds, portability checks, knob/note stress and WAV previews:', 'python3 fm1-base/rnbo-loader/hardware-tests/run.py --jobs 3', '# Native build for the first group, when Docker is accessible:', 'python3 fm1-base/rnbo-loader/hardware-tests/run.py --native --bank 1 --jobs 1', '# One patch only:', 'python3 fm1-base/rnbo-loader/hardware-tests/run.py --only t09_gendelay', '# Host-only screen/slot checks and the matched History comparison:', 'python3 fm1-base/rnbo-loader/hardware-tests/panel.py', 'python3 fm1-base/rnbo-loader/hardware-tests/compare.py', '```', '', 'For a native build, the resulting upload candidate is `fm1-base/rnbo-loader/build/hardware-tests/<id>/build/<id>.rnbom`. Require a passing native build and its `review.json` before uploading. The per-patch `module.json` is copied into the isolated build directory by the runner, including polyphony, shared-effect topology and memory caps. Use the runner for these test builds so those settings are retained.', '', 'Host WAV previews are at `build/hardware-tests/<id>/audition.wav`; the preview page is `build/hardware-tests/auditions.html`. The WAVs play four notes and, for polyphonic patches, a six-note stealing sequence. They are synthetic host output, not recordings from the FM1.', '', '## Hardware procedure for every group', '', '- Load its three native `.rnbom` files into slots 1, 2 and 3 and confirm the patch IDs on screen.', '- Play soft and hard notes, low and high keys, and fast repeated notes. Check stereo output and metering.', '- Test K1–K4, press FX, then test K5–K8. Confirm both the temporary name/value overlay and the audible result. Some controls need another control enabled; see each card.', '- Turn PRESETS while a note is held. A patch change may mute and clear effect tails; release and press the key again. No stuck note or crash should remain.', '- Change several controls, press SAVE, switch away and return. Power-cycle and check the saved values and startup slot. Repeat this for each slot.', '- Press PLAY for panic while notes or an effect tail are sounding. Confirm silence, then play a new note.', '- Record idle and held-note CPU, glitches and any resets. For the polyphonic group, include two-note and four-note measurements.', '- Watch the battery indicator and connect/disconnect USB during an ordinary playing check.', '- Keep default settings for the first pass, then sweep controls. High-feedback echoes can ring for many seconds; compare with feedback zero and use panic to distinguish an intended tail from a stuck note.', '', '## Test cards', '']
    for c, r in zip(cases, results):
        m = r['measurements']
        rows += [f"### Group {c['bank']}, slot {c['slot']}: {c['id']} — {c['title']}", '', c['listen'], '', '**Coverage:** ' + '; '.join(c['tests']) + '.', '', f"**Measured host allocation arena:** {m['pool_bytes']:,} / {m['pool_capacity']:,} bytes. This excludes the patch object, stack and other state; zero arena allocation does not mean zero RAM. Native qualification is recorded separately in HARDWARE-RESULTS.csv; the arena figures are host measurements.", '', f"[Editable Max patch](max/{c['id']}.maxpat) · [RNBO source]({c['source']})", '', '| Knob | Parameter | Range | Default |', '| --- | --- | --- | --- |']
        for i, p in enumerate(c['parameters']):
            rows.append(f"| K{i + 1} | {p['label']} | {num(p['min'])}–{num(p['max'])} {p['unit']} | {num(p['default'])} |")
        rows.append('')
        if c['id'] == 't03_lists':
            rows += ['Set Step to 63 before testing First. The source list is reversed, so the first stored item appears at the last selector position. Step 0 and Step 63 differ by two semitones at defaults; the host test checks that relationship.', '']
        if c['id'] == 't04_constants':
            rows += ['Set Blend above zero to hear Harmonic. Phase 0 and Phase 1 are the same phase; move through intermediate values. Ratio is a named Gen Param updated by RNBO messages, and its two endpoints were checked to change frequency by 16×.', '']
        if c['id'] in ['t05_history', 't06_nested']:
            rows += ['For the A/B comparison, set both patches to the same values, including Feedback (their initial feedback differs). The host comparison matched 327,680 sample words exactly while changing feedback and notes.', '']
        if c['id'] == 't08_table':
            rows += ['The 256-frame stereo table is generated inside the patch; no sample file is required. It fills in roughly 5.8 ms. The right channel reads the inverted table at the Offset phase, so mono summing at Offset 0 can cancel. Mix affects the left channel only. With 256 frames, nearest and linear reads are close: the default-setting host endpoint difference measured about 32 dB below the left signal. Pan left to isolate it, but a dramatic audible change is not expected.', '']
        if c['id'] == 't09_gendelay':
            rows += ['The two taps share one 2,048-sample delay. The right tap clamps at 2,048 samples when Time × Spread exceeds that limit. Compare Mix 0 and Mix 1 with short notes to verify dry/wet endpoints.', '']
        if c['id'] == 't13_fm2':
            rows += ['Hold two notes, add a third, then release the oldest key while the newer notes remain held. The stolen voice should not return and its old note-off should not silence the replacement.', '']
        if c['id'] in ['t14_fm4echo', 't15_hybrid']:
            rows += ['Repeat the stealing check with four held notes and a fifth/sixth note. Echo is one shared master effect. At Mix 1 a new short note should arrive through the delay without an immediate dry component.', '', 'The shared echo intentionally scales fresh input by `1 - Feedback`, then applies the dry/wet crossfade. At actual Feedback 0.90, a new short note enters the echo at -20 dB; at 0.98, about -34 dB. Mix 1 removes dry sound but does not recover that input attenuation. This explains T14’s quiet-echo observation. The unity-send/limited-loop revision was deferred; this repository retains the tested original gain design in T14 and T15.', '']
    rows += ['## Limits and findings', '', '- Gen buffers stay small: the table is 256 frames × 2 channels; the dual-tap delay is 2,048 samples. The RNBO comb/allpass test has an explicit 16 ms cap. The averaging test uses fixed 32-sample windows.', '- The four-voice echo and hybrid use the established 114,688-byte arena configuration; the other patches use their supplied settings. Do not infer native CPU or total RAM from the host arena figures.', '- The list patch uses `list.lookup` intentionally. RNBO 1.4.4 `list.nth` creates a temporary large-list copy on each call; with 64 items this violates the player’s no-late-allocation policy. That general `list.nth` limitation is not claimed fixed by this collection.', '- No FFT host context, external files, external audio input, Gen `voice`, `setparam` or unsupported wavetable `cycle` constructors are used. This is a practical hardware collection, not a replacement for the exhaustive compatibility fixtures.', '- The mono test patches have an output clamp at ±0.8; the polyphonic references retain their established gain structure. Listen for distortion at extreme settings rather than treating bounded output alone as proof of correct sound.', '- `design.py` regenerates the authored sources and overwrites edits to those generated files. Make a copy for personal experiments. `document.py` regenerates the guide, Max wrappers, reports and preview page; it preserves an existing hardware results CSV.', '']
    (ROOT / 'README.md').write_text('\n'.join(rows))
    csvpath = ROOT / 'HARDWARE-RESULTS.csv'
    if not csvpath.exists():
        columns = ['group', 'slot', 'patch', 'native_package_sha256', 'player_firmware_sha256', 'native_build', 'boot', 'notes_velocity', 'knobs_1_4', 'knobs_5_8', 'stereo_meters', 'battery_usb', 'save_restore', 'power_cycle', 'switch_held_note', 'panic', 'voice_stealing', 'cpu_idle_percent', 'cpu_1_note_percent', 'cpu_2_notes_percent', 'cpu_4_notes_percent', 'glitches_resets', 'result', 'notes']
        with csvpath.open('w', newline='') as f:
            w = csv.DictWriter(f, fieldnames=columns, lineterminator="\n")
            w.writeheader()
            for c in cases:
                w.writerow(dict(group=c['bank'], slot=c['slot'], patch=c['id']))
    cards = []
    for c in cases:
        cards.append(f'''<article><h2>{html.escape(c['id'])} · {html.escape(c['title'])}</h2><p>Group {c['bank']}, slot {c['slot']}</p><p>{html.escape(c['listen'])}</p><audio controls preload="none" src="{c['id']}/audition.wav"></audio></article>''')
    page = '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>FM1 RNBO test auditions</title><style>body{font:16px Arial,sans-serif;background:#404040;color:white;max-width:950px;margin:40px auto;padding:0 20px}h1{font-size:30px}article{border-top:1px solid #999;padding:18px 0}h2{font-size:19px}p{line-height:1.5;color:#eee}audio{width:100%}</style><h1>FM1 RNBO test auditions</h1><p>15 host-rendered previews. These are not FM1 recordings; consult the hardware results sheet for separately reported device observations.</p>' + ''.join(cards) + '</html>'
    (OUT / 'auditions.html').write_text(page)
    print('Wrote guide, Max wrappers, results sheet, host report and audition page')
if __name__ == '__main__':
    main()
